mapper.select:
SELECT r.id as id, r.user_id as athleteId, u.name as athleteName, u.gender as gender, g.name as deptName, u.email as contact, r.event_id as eventId, e.name as eventName, r.item_id as itemId, p.name as itemName, r.create_time as registrationTime, r.status as registrationStatus FROM registration r LEFT JOIN sys_user u ON r.user_id = u.id LEFT JOIN department g ON u.dept_id = g.id LEFT JOIN event e ON r.event_id = e.id LEFT JOIN event_item p ON r.item_id = p.id
AND r.event_id = #{eventId}
ORDER BY r.create_time DESC
